<?php
/**
 * Corrects the authority cited for South Carolina's comparative-negligence bar.
 *
 * S.C. Code § 15-38-15 governs APPORTIONMENT and joint and several liability
 * among DEFENDANTS. It does not establish the rule that bars a PLAINTIFF who is
 * more than fifty percent at fault -- that comes from Nelson v. Concrete Supply
 * Co., 303 S.C. 243, 399 S.E.2d 783 (1991).
 *
 * PR #97 corrected 34 pages of exactly this in August. THIRTY-ONE INSTANCES
 * SURVIVED OR WERE REINTRODUCED, across 23 pages -- including
 * /personal-injury-lawyers/charleston-sc/ three times, and a dozen local-SEO blog
 * posts that postdate the fix. The pattern is a template: a two-state comparison
 * table with a "Comparative fault threshold" row, and an FAQ answer explaining
 * partial fault.
 *
 * HOW THIS WAS FOUND, AND WHY THAT MATTERS. Reading the Charleston page while
 * copying its structure for the new Savannah page. A regex written specifically
 * to test for this class had already returned ZERO on the same content -- a false
 * negative from a sentence-boundary assumption. Every automated pass over this
 * class has now been wrong in one direction or the other, which is why all 76
 * occurrences of the section were read by eye before this list was built.
 *
 * 34 OF THE 76 ARE CORRECT AND ARE NOT TOUCHED. Where the citation is attached to
 * apportionment among multiple defendants, to joint and several liability, or to
 * the Act 42 amendment history on
 * /resources/south-carolina-liquor-liability-2026/, § 15-38-15 is exactly right.
 * Several pages contain BOTH a correct and an incorrect use, which is why each
 * edit is anchored on seventy characters of preceding context rather than on the
 * citation alone.
 *
 * One edit differs in shape: /blog/georgia-comparative-negligence-law/ said the
 * bar was "established through case law and codified in part under" the section.
 * A case name cannot be substituted into "codified under", so that clause is
 * rewritten to "established in Nelson v. Concrete Supply Co." instead.
 *
 * Run:  ssh $H "wp --path=... eval-file -" < bin/fix-nelson-comparative-bar.php
 *       (append ` apply` to write; default is a dry run)
 */

$APPLY = ( isset( $args[0] ) && 'apply' === $args[0] );
$EDITS = json_decode( base64_decode( '' ), true );
if ( ! is_array( $EDITS ) ) { echo "DECODE FAILED\n"; return; }

$backup = array(); $ok = true; $seen = array(); $applied = 0;

foreach ( $EDITS as $n => $e ) {
	$id = (int) $e['id']; $sn = $e['surface'];
	$orig = ( 'post_content' === $sn ) ? get_post_field( 'post_content', $id ) : get_post_meta( $id, $sn, true );
	$is_array = is_array( $orig );
	$hay = $is_array ? wp_json_encode( $orig, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) : (string) $orig;

	$hits = substr_count( $hay, $e['old'] );
	if ( ! $hits ) {
		// Already corrected by an earlier edit in this run whose anchor overlapped.
		if ( false !== strpos( $hay, $e['new'] ) ) { echo "SKIP  #$n {$e['path']} — already applied\n"; continue; }
		echo "REFUSE #$n {$e['path']} ({$sn}) — anchor not found\n"; $ok = false; continue;
	}

	$key = $id . '/' . $sn;
	if ( ! isset( $seen[ $key ] ) ) { $backup[] = array( 'id' => $id, 'surface' => $sn, 'before' => $hay ); $seen[ $key ] = true; }

	printf( "%s #%-2d %-3dx %s\n", $APPLY ? 'APPLY ' : 'DRYRUN', $n, $hits, $e['path'] );
	$applied += $hits;
	if ( ! $APPLY ) { continue; }

	$new = str_replace( $e['old'], $e['new'], $hay );
	if ( 'post_content' === $sn ) {
		$r = wp_update_post( array( 'ID' => $id, 'post_content' => $new ), true );
		if ( is_wp_error( $r ) ) { echo "   ERROR " . $r->get_error_message() . "\n"; $ok = false; }
	} elseif ( $is_array ) {
		$dec = json_decode( $new, true );
		if ( ! is_array( $dec ) ) { echo "   ERROR re-decode failed\n"; $ok = false; continue; }
		update_post_meta( $id, $sn, $dec );
	} else {
		update_post_meta( $id, $sn, $new );
	}
}

if ( $APPLY ) {
	echo "\n--- verify ---\n";
	$left = 0;
	foreach ( $EDITS as $e ) {
		$v = ( 'post_content' === $e['surface'] ) ? get_post_field( 'post_content', (int) $e['id'] ) : get_post_meta( (int) $e['id'], $e['surface'], true );
		$v = is_array( $v ) ? wp_json_encode( $v, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) : (string) $v;
		if ( false !== strpos( $v, $e['old'] ) ) { printf( "STILL PRESENT: %s\n", $e['path'] ); $left++; $ok = false; }
	}
	echo ( 0 === $left ) ? "all anchors replaced\n" : "$left remaining\n";
}

echo "\n" . wp_json_encode( array( 'applied' => $APPLY, 'edits' => count( $EDITS ), 'instances' => $applied, 'surfaces' => count( $seen ), 'ok' => $ok ) ) . "\n";

if ( ! $APPLY ) {
	echo "\n--- backup payload ---\n";
	$j = wp_json_encode( $backup, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE );
	echo ( false === $j ) ? 'ENCODE FAILED' : $j;
	echo "\n";
}
